'use strict';
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover: hover) and (pointer: fine)'),root=document.documentElement;
const reveals=[...document.querySelectorAll('.reveal')];if('IntersectionObserver'in window&&!reduced.matches){root.classList.add('js');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});reveals.forEach(el=>observer.observe(el))}
const toggle=document.querySelector('.menu-toggle'),heroObject=document.querySelector('.hero-object img'),gallery=document.querySelector('.gallery-row'),progress=document.querySelector('.page-progress');let scrollFrame=0;
function onScroll(){const max=root.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max?Math.min(scrollY/max,1):0})`;toggle.classList.toggle('show',scrollY>innerHeight*.55);if(!reduced.matches){heroObject.style.setProperty('--object-y',`${Math.min(scrollY*.16,140)}px`)}scrollFrame=0}
addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(onScroll)},{passive:true});addEventListener('resize',onScroll);onScroll();
const preview=document.getElementById('preview');let active=null,x=-200,y=-200,tx=-200,ty=-200,frame=0;
function draw(){x+=(tx-x)*.18;y+=(ty-y)*.18;preview.style.left=`${Math.max(180,Math.min(innerWidth-180,x))}px`;preview.style.top=`${Math.max(140,Math.min(innerHeight-140,y))}px`;frame=active&&Math.abs(tx-x)+Math.abs(ty-y)>.2?requestAnimationFrame(draw):0}
function hidePreview(){active=null;preview.classList.remove('visible');if(frame)cancelAnimationFrame(frame);frame=0}
document.querySelectorAll('.project').forEach(el=>{el.addEventListener('pointerenter',e=>{if(!fine.matches||reduced.matches)return;active=el;preview.querySelector('img').src=el.dataset.preview;tx=x=e.clientX;ty=y=e.clientY;preview.classList.add('visible');if(!frame)frame=requestAnimationFrame(draw)});el.addEventListener('pointermove',e=>{tx=e.clientX;ty=e.clientY;if(active&&!frame)frame=requestAnimationFrame(draw)});el.addEventListener('pointerleave',hidePreview);el.addEventListener('click',hidePreview)});addEventListener('blur',hidePreview);
for(const el of document.querySelectorAll('.magnetic')){el.addEventListener('pointermove',e=>{if(!fine.matches||reduced.matches)return;const r=el.getBoundingClientRect();el.style.transition='translate .4s cubic-bezier(.22,1,.36,1)';el.style.translate=`${(e.clientX-r.left-r.width/2)*.22}px ${(e.clientY-r.top-r.height/2)*.22}px`});el.addEventListener('pointerleave',()=>{el.style.transition='translate .7s cubic-bezier(.22,1,.36,1)';el.style.translate='0 0'})}
const menu=document.getElementById('menu');toggle.addEventListener('click',()=>{menu.showModal();toggle.setAttribute('aria-expanded','true');hidePreview()});document.querySelector('.menu-close').addEventListener('click',()=>menu.close());menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>menu.close()));menu.addEventListener('close',()=>toggle.setAttribute('aria-expanded','false'));menu.addEventListener('click',e=>{if(e.target!==menu)return;const r=menu.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)menu.close()});
reduced.addEventListener('change',()=>{if(reduced.matches){hidePreview();reveals.forEach(el=>el.classList.add('visible'));document.querySelectorAll('.magnetic').forEach(el=>el.style.translate='0 0');heroObject.style.removeProperty('--object-y')}});
const time=document.getElementById('local-time');function clock(){time.textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Shanghai'}).format(new Date())}clock();setInterval(clock,1000);document.getElementById('year').textContent=new Date().getFullYear();let toastTimer;document.getElementById('copy').addEventListener('click',async()=>{const t=document.getElementById('toast');try{await navigator.clipboard.writeText('13243503433');t.textContent='电话号码已复制'}catch{t.textContent='请长按复制：13243503433'}t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2800)});
// A native photo dialog supports click, keyboard arrows, Escape and focus return.
const photoButtons=[...document.querySelectorAll('[data-photo]')],viewer=document.getElementById('photo-viewer');let photoIndex=0,photoTrigger=null,viewerPhotos=photoButtons;
function showPhoto(index){photoIndex=(index+viewerPhotos.length)%viewerPhotos.length;const button=viewerPhotos[photoIndex];document.getElementById('viewer-image').src=button.dataset.photo;document.getElementById('viewer-image').alt=button.dataset.caption;document.getElementById('viewer-caption').textContent=`${photoIndex+1} / ${viewerPhotos.length} — ${button.dataset.caption}`;}
photoButtons.forEach(button=>button.addEventListener('click',()=>{photoTrigger=button;const group=button.closest('.gallery-row');viewerPhotos=group?[...group.querySelectorAll('[data-photo]')]:photoButtons.filter(photo=>!photo.closest('.gallery-row'));showPhoto(viewerPhotos.indexOf(button));viewer.showModal();hidePreview()}));document.querySelector('.photo-close').addEventListener('click',()=>viewer.close());document.querySelector('.photo-prev').addEventListener('click',()=>showPhoto(photoIndex-1));document.querySelector('.photo-next').addEventListener('click',()=>showPhoto(photoIndex+1));viewer.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(photoIndex-1)}if(e.key==='ArrowRight'){e.preventDefault();showPhoto(photoIndex+1)}});viewer.addEventListener('close',()=>photoTrigger?.focus({preventScroll:true}));viewer.addEventListener('click',e=>{if(e.target!==viewer)return;const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close()});

// Keep native touch/trackpad scrolling; release vertical wheel scrolling at either end.
const galleryPrev=document.querySelector('.gallery-prev'),galleryNext=document.querySelector('.gallery-next');
function updateGalleryControls(){const max=gallery.scrollWidth-gallery.clientWidth;galleryPrev.disabled=gallery.scrollLeft<=1;galleryNext.disabled=gallery.scrollLeft>=max-1}
function stepGallery(direction){const card=gallery.querySelector('.gallery-photo');const gap=parseFloat(getComputedStyle(gallery).columnGap)||0;gallery.scrollBy({left:direction*(card.getBoundingClientRect().width+gap),behavior:reduced.matches?'instant':'smooth'})}
galleryPrev.addEventListener('click',()=>stepGallery(-1));galleryNext.addEventListener('click',()=>stepGallery(1));
gallery.addEventListener('scroll',updateGalleryControls,{passive:true});addEventListener('resize',updateGalleryControls);updateGalleryControls();
gallery.addEventListener('wheel',event=>{if(event.ctrlKey||event.metaKey||event.shiftKey||Math.abs(event.deltaX)>=Math.abs(event.deltaY))return;const unit=event.deltaMode===1?16:event.deltaMode===2?gallery.clientWidth:1;const delta=event.deltaY*unit;const max=gallery.scrollWidth-gallery.clientWidth;if((delta>0&&gallery.scrollLeft>=max-1)||(delta<0&&gallery.scrollLeft<=1)||!delta)return;event.preventDefault();gallery.scrollLeft=Math.max(0,Math.min(max,gallery.scrollLeft+delta))},{passive:false});
